<?php require_once __DIR__.'/inc/functions.php'; if(is_logged_in())redirect('/students/index.php');$error='';$identity='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$identity=trim($_POST['identity']??'');$password=$_POST['password']??'';$q=db()->prepare('SELECT id,username,email,password FROM users WHERE username=? OR email=? LIMIT 1');$q->execute([$identity,$identity]);$u=$q->fetch();if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['username']=$u['username'];flash('success','تم تسجيل الدخول بنجاح.');redirect('/students/index.php');}else $error='بيانات الدخول غير صحيحة.';}$title='تسجيل الدخول';require __DIR__.'/inc/header.php'; ?>
<div class="form-card auth-card"><div class="form-heading"><span class="form-symbol">↗</span><span class="eyebrow">نظام تسجيل الطلاب</span><h1>مرحباً بعودتك</h1><p>سجّل الدخول للمتابعة إلى لوحة إدارة الطلاب.</p></div><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">اسم المستخدم أو البريد الإلكتروني</label><input class="form-control" name="identity" required value="<?=e($identity)?>" autocomplete="username"></div><div class="mb-3"><label class="form-label">كلمة المرور</label><input type="password" class="form-control" name="password" required autocomplete="current-password"></div><button class="btn btn-primary w-100">دخول</button></form><p class="mt-3 mb-0">ليس لديك حساب؟ <a href="<?=BASE_URL?>/register.php">أنشئ حساباً</a></p></div><?php require __DIR__.'/inc/footer.php'; ?>